 89 :         if (start == null || end == null) {
 90 :             throw new IllegalArgumentException("ReadablePartial objects must not be null");
 91 :         }
 92 :         if (start.size() != end.size()) {
 93 :             throw new IllegalArgumentException("ReadablePartial objects must have the same set of fields");
 94 :         }
 95 :         for (int i = 0, isize = start.size(); i < isize; i++) {
 96 :             if (start.getFieldType(i) != end.getFieldType(i)) {
 97 :                 throw new IllegalArgumentException("ReadablePartial objects must have the same set of fields");
 98 :             }
 99 :         }
100 :         if (DateTimeUtils.isContiguous(start) == false) {
101 :             throw new IllegalArgumentException("ReadablePartial objects must be contiguous");
102 :         }
103 :         Chronology chrono = DateTimeUtils.getChronology(start.getChronology()).withUTC();
104 :         int[] values = chrono.get(zeroInstance, chrono.set(start, 0L), chrono.set(end, 0L));
105 :         return values[0];
106 :     }
```"

